glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1.0);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform ARGS {
  vec4 paintColor;
  vec4 glowColor;
  float glowSize;
  float glowIntensity;
  float bgAlpha;
};
float sampleMaskA(vec2 uv) {
  if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
    return 0.0;
  }
  vec4 o = vec4(1.0);
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, uv);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, uv + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  #endif
  return o.a;
}
void accumulateRing(vec2 uv, float dist, float weight, inout float sum, inout float wSum) {
  sum += sampleMaskA(uv + vec2(dist, 0.0)) * weight;
  sum += sampleMaskA(uv + vec2(-dist, 0.0)) * weight;
  sum += sampleMaskA(uv + vec2(0.0, dist)) * weight;
  sum += sampleMaskA(uv + vec2(0.0, -dist)) * weight;
  sum += sampleMaskA(uv + vec2(dist, dist) * 0.7071) * weight;
  sum += sampleMaskA(uv + vec2(dist, -dist) * 0.7071) * weight;
  sum += sampleMaskA(uv + vec2(-dist, dist) * 0.7071) * weight;
  sum += sampleMaskA(uv + vec2(-dist, -dist) * 0.7071) * weight;
  wSum += weight * 8.0;
}
float gaussianBlurMask(vec2 uv, float sigma) {
  float s = max(sigma, 0.001);
  float sum = sampleMaskA(uv);
  float wSum = 1.0;
  float r1 = s * 0.35;
  float r2 = s * 0.60;
  float r3 = s * 0.85;
  float r4 = s * 1.15;
  float inv2s2 = 1.0 / (2.0 * s * s);
  accumulateRing(uv, r1, exp(-r1 * r1 * inv2s2), sum, wSum);
  accumulateRing(uv, r2, exp(-r2 * r2 * inv2s2), sum, wSum);
  accumulateRing(uv, r3, exp(-r3 * r3 * inv2s2), sum, wSum);
  accumulateRing(uv, r4, exp(-r4 * r4 * inv2s2), sum, wSum);
  return clamp(sum / max(wSum, 1e-4), 0.0, 1.0);
}
vec4 blendOver(vec4 src, vec4 dst) {
  float outA = src.a + dst.a * (1.0 - src.a);
  vec3 outRgb = src.rgb * src.a + dst.rgb * dst.a * (1.0 - src.a);
  if (outA > 1e-4) {
    outRgb /= outA;
  }
  return vec4(outRgb, outA);
}
void main () {
  vec4 base = vec4(1.0, 1.0, 1.0, 1.0);
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    base.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    base.a *= texture_tmp.a;
  #else
    base *= texture_tmp;
  #endif
  #endif
  base *= v_color;
  float maskA = clamp(base.a, 0.0, 1.0);
  float blurA = gaussianBlurMask(v_uv0, glowSize);
  float leak = max(0.0, blurA - maskA);
  float glowA = sqrt(leak) * glowIntensity * (1.0 - maskA);
  glowA = clamp(glowA, 0.0, 1.0) * glowColor.a;
  float paintA = clamp(maskA * paintColor.a, 0.0, 1.0);
  vec4 bg = vec4(v_color.rgb, clamp(v_color.a * bgAlpha, 0.0, 1.0));
  vec4 glow = vec4(glowColor.rgb, glowA);
  vec4 paint = vec4(paintColor.rgb, paintA);
  vec4 outColor = blendOver(glow, bg);
  outColor = blendOver(paint, outColor);
  ALPHA_TEST(outColor);
  gl_FragColor = outColor;
}

